sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    /**
     * MSSOTIQUBE--1095
     * Handle logic for state field check:update payload for"Processed" or create case/task for "Error" with error handling
     */
    try {
        var group = "assignment_group=79b74e581b9fd5906ed00e1ad34bcba9^stateNOT IN3,4,7";
        var retry_cnt = gs.getProperty("x_hsb11_hsbc_mss_o.event_outbound_retry_count");
        /**
         * MSSOTIQUBE-1095
         * If state field value is processed, it updates the response body in the payload field of the Business Process instance table
         */
        if (current.state == 'Processed') {
            var bpInstance = new GlideRecord('x_hsb11_hsbc_mss_o_business_process_instance');
            bpInstance.addQuery('financial_object_record', current.financial_object_id);
            bpInstance.query();
            if (bpInstance.next()) {
                bpInstance.payload = current.response_body;
                bpInstance.update();
            }
        }
        /**
         * MSSOTIQUBE-1095
         * If Error, it updates task with error handling implemented
         */
        else if (current.state == "Error" && current.retry_count >= retry_cnt) {

            var bpInstanceRecord = new GlideRecord('x_hsb11_hsbc_mss_o_business_process_instance');
            bpInstanceRecord.addQuery('financial_object_record', current.financial_object_id);
            bpInstanceRecord.query();
            if (bpInstanceRecord.next()) {
                var tradeCaseError = new GlideRecord("x_hsb11_hsbc_mss_t_trade_case");
                tradeCaseError.addQuery("u_business_process_instance", bpInstanceRecord.sys_id);
                tradeCaseError.query();
                if (tradeCaseError.next()) {
                    var tradeTaskError = new GlideRecord("x_hsb11_hsbc_mss_t_trade_task");
                    tradeTaskError.addQuery("parent", tradeCaseError.sys_id);
                    tradeTaskError.addEncodedQuery(group);
                    tradeTaskError.query();
                    if (tradeTaskError.next()) {
                        tradeTaskError.state = 7;
                        tradeTaskError.update();
                    }
                }
            }
            // Below two lines of code will trigger alert for error codes : 204,400,401,429,500
            // Calls the rest message configured to send widget failture details to ITID instance and creates an Event
            var failureDescription = "Cash Equities Event Outbound Widget failure, details of the error are as below - ServiceNow Reference -" + current.financial_object_id +" Trade ID: "+current.financial_object_id.u_id +" Timestamp : " + current.response_date + "Error code - " + current.error_code + "Error Body - " + current.error_body; //MSSOTIQUBE-1358
            var createEventForWidgetFailure = new x_hsb11_hsbc_mss_t.hsbcWidgetFailureHandler().createITIDEvent('WARNING', failureDescription, 'MSSiQubeSNWidget_EventLayer');
        }
    } catch (e) {
        gs.error("Unexpected error occurred during processing Equities event outbound response from EL: " + "Name: " + e.name + "  " + "Message: " + e.message); // MSSOTIQUBE-1095
    }

})(current, previous);
